    active = json.load(sys.stdin).get("stop_hook_active")
except Exception:
    active = False
if active:
    sys.exit(0)
try:
    out = subprocess.run([os.path.expanduser("~/toyl/docs/oyl-sync/pending.sh")], capture_output=True, text=True, timeout=20).stdout.strip()
except Exception:
    sys.exit(0)
if out:
    print(json.dumps({"decision": "block", "reason": "toyl has changed since Oyl last took it in. Before finishing, take these entries in as the toyl-sync skill says (make the changes, test headlessly, write the latest number into ~/Oyl/.toyl-sync, commit under the standing rule), then tell the owner in a line or two what changed:\n\n" + out}))'
